    var roughness = alb4.a;
    let sheenAmt = par.x;
    let aniso = par.y;
    let transmit = par.z;
    let weaveDepth = par.w;

    // ------------------------------------------------------------ weave detail
    let wuv = input.vUV * uniforms.weaveDensity;
    let dp1 = dpdx(world);
    let dp2 = dpdy(world);
